/* NEXO-INNOVA · PI2, equipo 4 · centro de decisiones vS6.
 * Los importes/paquetes/EVM proceden del Excel definitivo del usuario.
 * La conversión EAC → flujos de 36 meses y cambios de comportamiento son SUPUESTOS.
 * Sin servidores, cookies, métricas externas ni registro empresarial de avances.
 */
(() => {
'use strict';
const D=window.NEXO_SOURCE;
if(!D){document.body.innerHTML='<h1 style="padding:30px">Falta data.js. Publica los archivos juntos en la raíz de GitHub.</h1>';return;}
const $=q=>document.querySelector(q), $$=q=>Array.from(document.querySelectorAll(q));
const fmt=n=>Number(n).toLocaleString('es-CO',{maximumFractionDigits:0});
const money=n=>(n<0?'−':'')+'$'+fmt(Math.abs(Math.round(n)));
const moneyM=n=>(n<0?'−':'')+'$'+(Math.abs(n)/1e6).toLocaleString('es-CO',{maximumFractionDigits:2,minimumFractionDigits:2})+' M';
const pct=(n,d=2)=>Number(n*100).toLocaleString('es-CO',{maximumFractionDigits:d,minimumFractionDigits:d})+' %';
const dec=(n,d=3)=>Number(n).toLocaleString('es-CO',{maximumFractionDigits:d,minimumFractionDigits:d});
const clamp=(n,a,b)=>Math.max(a,Math.min(b,Number(n)||0));
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const tags={source:'<span class="data-tag">Fuente Excel S6</span>',assume:'<span class="data-tag assumption">Supuesto</span>',sim:'<span class="data-tag sim">Simulación</span>',interpret:'<span class="data-tag interpret">Interpretación</span>'};
const names={panorama:'Panorama ejecutivo',decisiones:'Decisiones y escenarios',edt:'EDT y cronograma',riesgos:'Riesgos y gates',trazabilidad:'Evolución y análisis'};
const initial=()=>({tab:'panorama',finance:'base',execution:'A',futureMode:'observed',futureCpi:1,evidencePct:0,extraHours:0,delay:0,capturePct:100,iterationDelta:0,linkCost:true,expenseMonth:6,privacyVeto:false,legalVeto:false,gates:{G0:false,G1:false,G2:false,G3:false},selectedPackage:'1.1.1',account:'all',gateFilter:'all',packageSearch:'',riskGroup:'Todos',riskSearch:'',selectedRisk:'RT1',actorVersion:'v1',archiveTab:'evolucion',archiveH:'H2',archiveActor:'A08',archiveDelta:'cliente'});
let S=initial();
let toastTimer;
function toast(msg){const el=$('#toast');if(!el)return;el.textContent=msg;el.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('visible'),3000)}
function nav(id){if(!names[id])return;S.tab=id;$$('.view').forEach(x=>x.classList.toggle('active',x.id==='view-'+id));$$('.nav-item').forEach(x=>{const active=x.dataset.tab===id;x.classList.toggle('active',active);if(active)x.setAttribute('aria-current','page');else x.removeAttribute('aria-current')});$('#crumbCurrent').textContent=names[id];$('#sidebar').classList.remove('open');renderCurrent();window.scrollTo({top:0,behavior:'instant'});}
function getEVM(code=S.execution){
 const ref=D.evmCases.find(x=>x.id===code)||D.evmCases[0];
 const pv=ref.pv;
 // Recalcular EV desde cada paquete: la regla 0/100 impide aceptar fracciones de gates.
 const ev=D.packages.reduce((sum,p)=>{
  const scheduled=p.pvByPhase.slice(0,4).reduce((a,b)=>a+b,0);
  if(!scheduled)return sum;
  const factor=code==='A'?1:code==='B'?p.evFactorB:p.evFactorC;
  const base=p.evRule==='0/100'?(factor>=1?scheduled:0):scheduled*factor;
  const outstanding=scheduled-base;
  const newlyAccepted=p.evRule==='0/100'?(S.evidencePct===100?outstanding:0):outstanding*S.evidencePct/100;
  return sum+base+newlyAccepted;
 },0);
 const ac=ref.ac+S.extraHours*D.costHour;
 const spi=pv>0?ev/pv:null,cpi=ac>0?ev/ac:null;
 const isValid=ev>0 && ac>0,observedCpi=cpi||0;
 const eacWork=isValid?(S.futureMode==='observed'?D.bac/observedCpi:ac+(D.bac-ev)/S.futureCpi):null;
 const reserve=eacWork==null?null:Math.max(0,D.reserve-Math.max(0,eacWork-D.bac));
 const commitment=eacWork==null?null:eacWork+reserve;
 const excess=commitment==null?null:commitment-D.investment;
 const tcpi=D.bac>ac?(D.bac-ev)/(D.bac-ac):null;
 return {case:code,ref,pv,ev,ac,sv:ev-pv,cv:ev-ac,spi,cpi,eacWork,reserve,commitment,excess,tcpi};
}
function financialResult(key=S.finance,ec=S.execution){
 const f=D.financialCases.find(x=>x.id===key)||D.financialCases[1],e=getEVM(ec);
 const annualRate=.1,monthlyRate=Math.pow(1+annualRate,1/12)-1;
 const iter=Math.max(0,f.iterations+S.iterationDelta),capture=f.capture.map(v=>Math.min(1,Math.max(0,v*S.capturePct/100)));
 const extraEac=S.linkCost&&e.excess!=null?Math.max(0,e.excess):0;
 let npv=0,pvBen=0,pvCost=0,cumulative=0,payback=null,rows=[],flows=[];
 for(let m=0;m<=36;m++){
  const t=m-S.delay,idx=t>=3&&t<=12?0:t>=13&&t<=24?1:t>=25&&t<=36?2:-1;
  // Exact structure of the PI2 S4/S5 model, unit valuation rounded as reported there.
  const benefit=idx<0?0:15*iter*266779.78*capture[idx];
  let investment=m===0?3969000:m===1?10620000:m===2?6838500:0;
  if(m===S.expenseMonth)investment+=extraEac;
  const net=benefit-investment,present=net/Math.pow(1+monthlyRate,m);
  const previous=cumulative;cumulative+=present;npv+=present;
  pvBen+=benefit/Math.pow(1+monthlyRate,m);pvCost+=investment/Math.pow(1+monthlyRate,m);
  if(payback==null&&m>0&&previous<0&&cumulative>=0&&present>0)payback=m-1-previous/present;
  rows.push({month:m,benefit,investment,net,present,cumulative});flows.push(net);
 }
 const fRate=r=>flows.reduce((sum,v,i)=>sum+v/Math.pow(1+r,i),0);
 let irr=null,low=-.95,high=2;
 if(fRate(low)*fRate(high)<0){for(let i=0;i<75;i++){const mid=(low+high)/2;if(fRate(mid)*fRate(low)>0)low=mid;else high=mid}irr=Math.pow(1+(low+high)/2,12)-1;}
 return {key,ec,ref:f,evm:e,iterations:iter,capture,extraEac,npv,irr,bc:pvCost>0?pvBen/pvCost:null,payback,rows,pvBen,pvCost};
}
function reportRecommendation(x=financialResult()){
 if(S.privacyVeto||S.legalVeto)return {type:'critical',title:'BLOQUEAR GATE',text:'Existe un veto hipotético de privacidad o cumplimiento: ningún CPI, SPI ni VPN positivo permite continuar sin resolverlo.'};
 if(x.evm.excess>0 && x.evm.excess>0.1*D.investment)return {type:'critical',title:'REPROGRAMAR Y REVISAR',text:'El EAC de compromiso sobrepasa materialmente la inversión. Revisar evidencia aceptada, cadena de riesgo y productividad antes de comprometer más recursos.'};
 if(x.npv<=0)return {type:'critical',title:'NO ESCALAR · REVISAR BENEFICIOS',text:'El VPN proyectado no es positivo bajo los supuestos activos. Revisar adopción, iteraciones efectivamente evitables, demora y costos.'};
 if(!Object.values(S.gates).every(Boolean))return {type:'info',title:'PILOTO CONDICIONADO',text:'Los resultados ilustrativos son favorables, pero siguen pendientes condiciones y evidencia de uno o más gates. El análisis no autoriza inversión ni escalamiento.'};
 return {type:'ok',title:'RECOMENDAR REVISIÓN FORMAL',text:'La simulación supera los controles seleccionados, pero las marcas no son actas. El sponsor y Finanzas deben verificar evidencias y decidir.'};
}
const metric=(label,value,sub,tone='')=>`<article class="metric ${tone}"><small>${esc(label)}</small><strong>${value}</strong><span>${esc(sub)}</span></article>`;
const notice=(text,kind='')=>`<div class="notice ${kind}">${text}</div>`;
const sectionTop=(n,title,subtitle,id)=>`<div class="section-top"><span class="eyebrow">${n} · NEXO-INNOVA · PI2</span><h1 id="${id}">${title}</h1><p class="intro">${subtitle}</p></div>`;
function accountRows(){const max=Math.max(...D.accounts.map(a=>a.bac));return D.accounts.map(a=>`<div class="account-row"><span class="idx">${a.id}</span><div><span class="label">${esc(a.name)}</span><div class="bar-track"><div class="bar-fill" style="width:${a.bac/max*100}%"></div></div></div><span class="amt">${moneyM(a.bac)}</span></div>`).join('');}
function threeFinanceCards(selected=S.finance){return D.financialCases.map(f=>{const v=financialResult(f.id);return `<button type="button" class="scenario-mini ${f.id===selected?'active':''}" data-finance="${f.id}" style="text-align:left;cursor:pointer"><strong>${f.name}</strong><b class="${v.npv<0?'text-red':'text-green'}">${moneyM(v.npv)}</b><span>VPN original ${moneyM(f.npv)} · ${dec(f.iterations,2)} iter./caso</span></button>`}).join('');}
function financialBars(){const entries=D.financialCases.map(c=>financialResult(c.id)),maximum=Math.max(...entries.map(x=>Math.abs(x.npv)),1);return `<div class="divergent">${entries.map(x=>{const length=Math.min(49,Math.abs(x.npv)/maximum*48),isPos=x.npv>=0,style=isPos?`left:50%;width:${length}%`:`right:50%;width:${length}%`;return `<div class="div-row"><strong>${esc(x.ref.name)}</strong><div class="div-bar"><span class="${isPos?'pos':'neg'}" style="${style}"></span></div><b class="${isPos?'text-green':'text-red'}">${moneyM(x.npv)}</b></div>`}).join('')}</div>`;}
function pvChart(){const w=820,h=250,px=68,py=32,right=16,bottom=45;
 const vals=D.investmentPhase.map((x,i)=>({phase:x.phase,pv:D.pvPhase[x.phase]||0,spend:x.direct+x.indirect,reserve:x.reserve}));
 const max=Math.max(...vals.map(x=>Math.max(x.pv,x.spend,x.reserve)),1)*1.13;
 const xx=i=>px+(w-px-right)*i/7, yy=v=>h-bottom-(h-py-bottom)*v/max;
 const path=key=>vals.map((z,i)=>(i?'L':'M')+xx(i).toFixed(1)+' '+yy(z[key]).toFixed(1)).join(' ');
 const grid=[0,.25,.5,.75,1].map(t=>`<line x1="${px}" y1="${yy(max*t)}" x2="${w-right}" y2="${yy(max*t)}" stroke="#e2eaed" stroke-dasharray="4 5"/><text x="${px-10}" y="${yy(max*t)+4}" fill="#718693" text-anchor="end" font-size="11">${(max*t/1e6).toFixed(1)}M</text>`).join('');
 const dots=vals.map((z,i)=>`<circle cx="${xx(i)}" cy="${yy(z.pv)}" r="4" fill="#168c87"/><circle cx="${xx(i)}" cy="${yy(z.spend)}" r="4" fill="#e4a64c"/>${z.reserve?`<circle cx="${xx(i)}" cy="${yy(z.reserve)}" r="5" fill="#ad88c6"/>`:''}<text x="${xx(i)}" y="${h-14}" fill="#6f8491" text-anchor="middle" font-size="11">${z.phase}</text>`).join('');
 return `<svg class="chart-svg" viewBox="0 0 ${w} ${h}" role="img" aria-label="Comparación PV trabajo, inversión de referencia y contingencia en P7">${grid}<path d="${path('pv')}" stroke="#168c87" fill="none" stroke-width="3" stroke-linejoin="round"/><path d="${path('spend')}" stroke="#e4a64c" fill="none" stroke-width="3" stroke-linejoin="round"/><path d="${path('reserve')}" stroke="#ad88c6" fill="none" stroke-width="2" stroke-dasharray="5 4"/>${dots}</svg><div class="chart-legend"><span>PV del trabajo</span><span class="investment">Costos del flujo P0–P6</span><span class="reserve">EMV en P7 (reserva)</span></div>`;
}
function panorama(){const e=getEVM(),f=financialResult(),rec=reportRecommendation(f);
 return `<section class="hero"><div><span class="eyebrow">CENTRO DE MANDO · NOVIEMBRE 2026</span><h1 id="panoramaTitle">Del análisis a la decisión.</h1><p>Una lectura de NEXO-INNOVA desde las hipótesis de negocio hasta sus 26 entregables, los riesgos, el desempeño de ejecución y los tres escenarios financieros. Todo se mantiene conectado y diferenciado entre fuentes y supuestos.</p><div class="hero-actions"><button class="primary-btn" data-go="decisiones">Explorar impacto de decisiones ↗</button><button class="ghost-btn" data-go="edt">Consultar los 26 paquetes</button></div></div></section>
 <div class="metric-grid">${metric('Inversión económica',moneyM(D.investment),'Trabajo + reserva EMV')}${metric('BAC del trabajo',moneyM(D.bac),'100 % asignado a 26 paquetes')}${metric('Reserva EMV incluida',moneyM(D.reserve),'No genera PV ni EV')}${metric('Horizonte propuesto','20 + 1 sem.','S21: buffer de fecha')}</div>
 ${archiveQuick()}
 <div class="columns2 mb18"><article class="surface"><div class="panel-heading"><div><h3>¿En qué se concentra el trabajo?</h3><p>Ocho cuentas de control; distribución tomada del Excel definitivo.</p></div>${tags.source}</div>${accountRows()}<p class="footnote">Formación, cambio/comunicaciones y acompañamiento concentran el 50,4 % del BAC. Todos los valores son presupuestos de referencia, no gastos realizados.</p></article><article class="surface"><div class="panel-heading"><div><h3>Viabilidad: tres escenarios</h3><p>Modelo de 36 meses · TIO supuesta 10 % E.A.</p></div>${tags.sim}</div>${financialBars()}<div class="source-line"><b>Referencia del Excel:</b> VPN conservador ${moneyM(D.financialCases[0].npv)}, base ${money(D.financialCases[1].npv)} y favorable ${moneyM(D.financialCases[2].npv)}.<br>El caso base tiene una holgura de apenas ${money(D.financialCases[1].npv)} en valor presente.</div><button class="nav-link-inline" data-go="decisiones" style="margin-top:13px">Ver todas las combinaciones →</button></article></div>
 <div class="columns2 mb18"><article class="surface"><div class="panel-heading"><div><h3>Separar tres cifras que suelen confundirse</h3><p>Corte de control P3 · ${tags.source}</p></div></div><div class="kpi-summary"><div><strong>PV · valor programado</strong><small>Trabajo que debió estar listo al corte</small></div><b>${money(e.pv)}</b></div><div class="kpi-summary"><div><strong>EV · valor ganado</strong><small>En la simulación, entregables que cumplen la regla de EV</small></div><b>${money(e.ev)}</b></div><div class="kpi-summary"><div><strong>AC · costo incurrido</strong><small>Costos de referencia de la simulación, no gasto comprobado</small></div><b>${money(e.ac)}</b></div><div class="notice info" style="margin-top:14px">Escenario EVM activo: <b>${e.case}</b>. El cambio A/B/C representa estados de ejecución distintos del conservador/base/favorable financiero.</div></article>
 <article class="surface"><div class="panel-heading"><div><h3>Conclusión bajo la simulación actual</h3><p>Una lectura conjunta de desempeño, evidencia y valor económico</p></div>${tags.interpret}</div><div class="notice ${rec.type}"><strong>${rec.title}</strong><p style="margin:6px 0 0">${rec.text}</p></div><div class="result-grid" style="margin-top:15px;margin-bottom:0"><div class="result-stat"><small>SPI</small><strong>${dec(e.spi)}</strong><span>AVANCE RELATIVO</span></div><div class="result-stat"><small>CPI</small><strong>${dec(e.cpi)}</strong><span>EFICIENCIA DE COSTO</span></div><div class="result-stat"><small>VPN seleccionado</small><strong style="font-size:17px">${moneyM(f.npv)}</strong><span>${D.financialCases.find(z=>z.id===S.finance).name}</span></div></div><p class="footnote">Las recomendaciones son reglas académicas condicionadas. No reemplazan al sponsor, Finanzas ni la aceptación documentada.</p></article></div>
 <section class="surface mb18"><div class="panel-heading"><div><h3>Una ruta en cinco preguntas</h3><p>Selecciona cualquier etapa para profundizar. El camino explica la cadena de valor, no solo las materias.</p></div></div><div class="journey"><button class="journey-item" data-step="01 · POR QUÉ" data-go="trazabilidad"><strong>Estrategia</strong><small>Canvas, entorno, BSC y OKR</small></button><button class="journey-item" data-step="02 · QUÉ" data-go="edt"><strong>EDT</strong><small>26 salidas verificables</small></button><button class="journey-item" data-step="03 · QUÉ PODRÍA FALLAR" data-go="riesgos"><strong>Riesgos</strong><small>Gate, disparador, respuesta</small></button><button class="journey-item" data-step="04 · CÓMO VA" data-go="decisiones"><strong>EVM</strong><small>PV, EV, AC y pronóstico</small></button><button class="journey-item" data-step="05 · VALE LA PENA" data-go="decisiones"><strong>VPN</strong><small>Escenarios y criterio de continuidad</small></button></div></section>
 ${notice('<b>Trazabilidad:</b> 8 cuentas, 26 paquetes, importes, 7 fases de PV y casos A/B/C provienen del Excel S6. Las correlaciones, variaciones de CPI futuro y conversión del EAC a flujo de caja son ensayos explícitos, no datos corporativos.', 'info')}`;
}
function evmBar(e){const vals=[['PV',e.pv,'#76bbc2'],['EV',e.ev,'#248d80'],['AC',e.ac,'#e6a25f']];const max=Math.max(...vals.map(x=>x[1]),1);return `<div class="rows" style="gap:12px">${vals.map(([lab,v,color])=>`<div><div style="display:flex;justify-content:space-between;font-size:12px"><b>${lab}</b><strong>${money(v)}</strong></div><div class="bar-track" style="height:12px"><div class="bar-fill" style="background:${color};width:${Math.max(0,v/max*100)}%"></div></div></div>`).join('')}</div>`;}
function chainFlow(f){const e=f.evm;return `<div class="cause-flow"><div class="node"><small>01 · DECISIÓN</small><strong>${S.execution==='A'?'Ejecución conforme':S.execution==='B'?'Validaciones y retrabajo':'Cadena de bloqueos'}</strong></div><div class="node"><small>02 · ENTREGABLE</small><strong>${money(e.ev)} EV aceptable*</strong></div><div class="node"><small>03 · DESVIACIÓN</small><strong>CPI ${dec(e.cpi)} · SPI ${dec(e.spi)}</strong></div><div class="node"><small>04 · PRONÓSTICO</small><strong>${moneyM(e.commitment)} EAC</strong></div><div class="node"><small>05 · VALOR</small><strong class="${f.npv<0?'text-red':'text-green'}">${moneyM(f.npv)} VPN</strong></div></div><p class="footnote">*Aceptación hipotética conforme a factores y regla de EV del libro S6. La última conexión supone llevar el exceso de EAC al flujo financiero; puede desactivarse.</p>`;}
function scenarioMatrix(){const head=D.financialCases.map(f=>`<th>${f.name}<br><small>${dec(f.iterations,2)} iter./caso</small></th>`).join('');let body=D.evmCases.map(e=>`<tr><th>${e.id}<br><small>${e.name.slice(4)}</small></th>${D.financialCases.map(f=>{const v=financialResult(f.id,e.id);return `<td class="${v.npv>=0?'positive':'negative'} ${S.execution===e.id&&S.finance===f.id?'selected':''}"><button type="button" data-matrix="${e.id}|${f.id}" title="Ver estado ${e.id} y escenario ${f.name}">${moneyM(v.npv)}</button><small>${v.npv>=0?'VPN positivo supuesto':'VPN no positivo'}</small></td>`}).join('')}</tr>`).join('');return `<div class="table-scroller"><table class="matrix"><thead><tr><th>Estado EVM ↓ / economía →</th>${head}</tr></thead><tbody>${body}</tbody></table></div>`;}
function decisions(){const e=getEVM(),f=financialResult(),rec=reportRecommendation(f);return `${sectionTop('02 · SIMULADOR','Del riesgo al valor económico','Prueba cómo una decisión cambia la evidencia aceptada, los costos, el pronóstico EAC y los tres VPN. A/B/C son estados de ejecución; conservador/base/favorable son supuestos de beneficios. Son dimensiones independientes.','decisionesTitle')}
 <div class="columns2 mb18" style="grid-template-columns:.91fr 1.09fr"><div class="stack"><section class="surface"><div class="panel-heading"><div><h3>1 · Estado de ejecución (EVM)</h3><p>Casos documentados · corte P3, semanas 9–11</p></div>${tags.source}</div><div class="scenario-tabs">${D.evmCases.map(x=>`<button class="choice ${x.id===S.execution?'active':''} ${x.id==='C'?'danger':''}" data-execution="${x.id}">${x.id} · ${x.id==='A'?'Referencia':x.id==='B'?'Desviación':'Estrés severo'}</button>`).join('')}</div><p class="tabs-hint">A: conforme al plan · B: datos, validación y quórum · C: cadena de fallas de datos, adopción y versiones.</p><div class="control-card"><h4>Correcciones sobre el corte, solo para ensayar</h4><div class="field"><div class="control-caption"><label for="evidencePct">Aceptar evidencia pendiente simulada</label><strong class="readout" id="r-evidencePct">${S.evidencePct} %</strong></div><input type="range" id="evidencePct" min="0" max="100" step="5" value="${S.evidencePct}" data-range="evidencePct"><span class="help">Reacredita evidencia de paquetes ponderados; los paquetes 0/100 solo ganan EV al completar el 100 % (hipótesis, no acta).</span></div><div class="field"><div class="control-caption"><label for="extraHours">Horas correctivas adicionales</label><strong class="readout" id="r-extraHours">${S.extraHours} h</strong></div><input type="range" id="extraHours" min="0" max="150" step="5" value="${S.extraHours}" data-range="extraHours"><span class="help">${money(D.costHour)}/h asumidos en Excel · incremento de AC aparte del costo ya simulado.</span></div></div><div class="control-card"><h4>Productividad que se espera en el trabajo restante</h4><div class="switcher"><button class="choice ${S.futureMode==='observed'?'active':''}" data-futuremode="observed">Persistir CPI actual</button><button class="choice ${S.futureMode==='recovered'?'active':''}" data-futuremode="recovered">Recuperación / nuevo CPI</button></div>${S.futureMode==='recovered'?`<div class="field" style="margin-top:14px"><div class="control-caption"><label for="futureCpi">CPI futuro</label><strong class="readout" id="r-futureCpi">${dec(S.futureCpi,2)}</strong></div><input type="range" id="futureCpi" min="0.4" max="1.4" step="0.05" value="${S.futureCpi}" data-range="futureCpi"><span class="help">EAC trabajo = AC + (BAC − EV) / CPI futuro; no cambia el CPI observado del corte.</span></div>`:`<p class="quiet" style="margin:13px 0 0">EAC trabajo = BAC / CPI observado. Extrapolación académica del estado actual.</p>`}</div></section>
 <section class="surface"><div class="panel-heading"><div><h3>2 · Hipótesis de beneficios</h3><p>Afectan a los tres casos financieros al mismo tiempo</p></div>${tags.assume}</div><div class="field"><label for="delay">Demora del comienzo de beneficios <b class="readout" id="r-delay">${S.delay} meses</b></label><input type="range" data-range="delay" id="delay" min="0" max="12" step="1" value="${S.delay}"><span class="help">Un bloqueo de gate puede retrasar la captura (no cambia por sí solo el SPI).</span></div><div class="field"><label for="capturePct">Realización relativa del beneficio <b class="readout" id="r-capturePct">${S.capturePct} %</b></label><input type="range" data-range="capturePct" id="capturePct" min="40" max="120" step="5" value="${S.capturePct}"><span class="help">Escala captura prevista en S4, con límite de 100 % por tramo.</span></div><div class="field"><label for="iterationDelta">Variación en iteraciones evitadas <b class="readout" id="r-iterationDelta">${S.iterationDelta>=0?'+':''}${dec(S.iterationDelta,2)} / desarrollo</b></label><input type="range" data-range="iterationDelta" id="iterationDelta" min="-0.1" max="0.1" step="0.01" value="${S.iterationDelta}"><span class="help">Se añade al 0,15 / 0,25 / 0,35 de cada escenario; no son iteraciones observadas.</span></div><div class="control-card" style="margin-top:14px"><label class="toggle-line"><input type="checkbox" data-checkbox="linkCost" ${S.linkCost?'checked':''}><span><strong>Propagar exceso de EAC al VPN</strong><small>Se adiciona exclusivamente el exceso sobre ${money(D.investment)} de inversión; EMV incluida y nunca duplicada.</small></span></label><div class="field"><label for="expenseMonth">Mes supuesto del costo adicional</label><select id="expenseMonth" ${!S.linkCost?'disabled':''}>${[0,3,6,9,12].map(m=>`<option value="${m}" ${S.expenseMonth===m?'selected':''}>Mes ${m}${m===6?' · supuesto inicial':''}</option>`).join('')}</select><span class="help">El libro no define el mes exacto del sobrecosto EVM. Selección ilustrativa para descontarlo en el flujo de 36 meses.</span></div></div></section>
 <section class="surface"><div class="panel-heading"><div><h3>3 · Evidencia y vetos</h3><p>Marcación académica, nunca una aprobación real</p></div>${tags.sim}</div><div class="small-cards">${D.gates.map(g=>`<label class="small-card accept-check" style="border-top:1px solid var(--line);align-items:center"><input type="checkbox" data-gatecheck="${g.id}" ${S.gates[g.id]?'checked':''}><span><strong>${g.id} · ${g.name}</strong><small style="display:block;font-size:10px;color:var(--muted)">${g.window}</small></span></label>`).join('')}</div><label class="toggle-line"><input type="checkbox" data-checkbox="privacyVeto" ${S.privacyVeto?'checked':''}><span><strong>Activar veto de acceso / privacidad (RI4)</strong><small>Bloquea la recomendación de avanzar aunque el VPN sea positivo.</small></span></label><label class="toggle-line"><input type="checkbox" data-checkbox="legalVeto" ${S.legalVeto?'checked':''}><span><strong>Activar veto normativo (RE1)</strong><small>G1/G2 requieren cumplimiento, independiente del CPI.</small></span></label></section></div>
 <div class="stack"><section class="surface"><div class="panel-heading"><div><h3>Resultado de la ejecución seleccionada</h3><p>${e.ref.name} · corte simulado P3</p></div>${tags.sim}</div><div id="simMetrics">${simMetrics(e,f)}</div></section>
 <section class="surface"><div class="panel-heading"><div><h3>4 · Escenario de negocio</h3><p>Elige el que quieres detallar. Las tres columnas se calculan con las mismas decisiones.</p></div>${tags.source}</div><div class="mini-scenario-grid" id="scenarios3">${threeFinanceCards()}</div><div class="notice info" style="margin-top:14px" id="financeReading">${financeReading(f)}</div></section>
 <section class="surface"><div class="panel-heading"><div><h3>Consecuencia sobre el flujo de caja</h3><p>VPN, TIR y recuperación recalculados a 36 meses</p></div>${tags.sim}</div><div id="financeMetrics">${financeMetrics(f)}</div></section>
 <section class="surface"><div class="panel-heading"><div><h3>Criterio gerencial condicionado</h3><p>Desempeño + cumplimiento + valor demostrable</p></div>${tags.interpret}</div><div id="recommendation">${notice(`<b>${rec.title}</b><p style="margin:6px 0 0">${rec.text}</p>`,rec.type)}</div><div class="row-buttons" style="margin-top:13px"><button class="secondary-btn" data-reset>↺ Restablecer controles</button><button class="secondary-btn" data-export="decisions">↓ Resultados CSV</button></div></section></div></div>
 <section class="surface mb18"><div class="panel-heading"><div><h3>La consecuencia paso a paso</h3><p>Selecciona cualquier escenario y observa la propagación bajo supuestos explícitos.</p></div></div><div id="chainHost">${chainFlow(f)}</div></section>
 <section class="surface mb18"><div class="panel-heading"><div><h3>Matriz 3 × 3 · los nueve resultados posibles</h3><p>Filas = estado EVM A/B/C; columnas = hipótesis financiera. Toca una celda para inspeccionar sus métricas.</p></div><span class="data-tag sim">Cruce condicional</span></div><div id="matrixHost">${scenarioMatrix()}</div><p class="footnote">El EAC NO es un VPN. La cifra de cada celda es una prueba de sensibilidad que agrega el exceso del EAC al flujo de referencia solo cuando está activado «Propagar exceso de EAC». No presupone autorización, ocurrencia ni fecha cierta del gasto.</p></section>
 ${notice('Pistas de control: una aceptación incrementa EV sin borrar AC; horas correctivas suben AC aunque no exista EV; recuperar CPI futuro modifica el EAC, pero no altera el CPI histórico. SPI no determina una fecha sin revisar dependencias y gates.', 'info')}`;
}
function simMetrics(e,f){let x=e.excess,over=x>0;return `<div class="result-grid">${[['PV',money(e.pv),'Programado'],['EV',money(e.ev),'Aceptación simulada'],['AC',money(e.ac),'Costo a corte'],['SPI',dec(e.spi),'Alerta si <0,95'],['CPI',dec(e.cpi),'Alerta si <0,95'],['EAC compromiso',moneyM(e.commitment),'Incluye EMV pendiente']].map(([name,val,sub],i)=>`<div class="result-stat ${i===5&&over?'negative':i===4&&e.cpi>=.95?'positive':''}"><small>${name}</small><strong style="font-size:${val.length>13?'16':'19'}px">${val}</strong><span>${sub}</span></div>`).join('')}</div>${evmBar(e)}<div class="source-line" style="margin-top:14px"><b>Fórmulas:</b> SV = EV − PV = ${money(e.sv)} · CV = EV − AC = ${money(e.cv)} · TCPI ${e.tcpi==null?'no viable con BAC (AC ≥ BAC)':dec(e.tcpi)}. Reserva pendiente ${money(e.reserve)} (dentro del techo, no EV).<br><b>Exceso frente al techo:</b> <span class="${e.excess>0?'text-red':'text-green'}">${money(e.excess)}</span>.</div>`;}
function financeReading(f){return `<b>${esc(f.ref.name)}:</b> ${dec(f.iterations,2)} iteraciones evitadas por desarrollo (hipótesis aplicada); captura ${(f.capture.map(x=>pct(x,0))).join(' / ')} en A1/A2/A3. Costo extra por EAC incluido: ${money(f.extraEac)} <i>en mes ${S.expenseMonth} supuesto</i>. VPN de referencia de la hoja 08: ${money(f.ref.npv)}.`;}
function financeMetrics(f){return `<div class="result-grid">${[['VPN',money(f.npv),'10 % E.A. supuesto'],['TIR anual',f.irr==null?'N/C':pct(f.irr,2),'37 flujos, meses 0–36'],['B/C',dec(f.bc,3),'Valor presente'],['Payback descontado',f.payback==null?'No recupera':dec(f.payback,2)+' meses','Hasta el mes 36'],['Δ VPN vs. Excel',money(f.npv-f.ref.npv),'Sensibilidad acumulada'],['Gasto EAC agregado',money(f.extraEac),'Sin duplicar EMV']].map(([label,val,sub],i)=>`<div class="result-stat ${i===0?(f.npv>0?'positive':'negative'):''}"><small>${label}</small><strong style="font-size:${String(val).length>14?'15':'19'}px">${val}</strong><span>${sub}</span></div>`).join('')}</div>`;}
function edtsFiltered(){return D.packages.filter(p=>(S.account==='all'||p.account===S.account)&&(S.gateFilter==='all'||p.gate===S.gateFilter)&&(`${p.id} ${p.name} ${p.owner} ${p.risk}`.toLowerCase().includes(S.packageSearch.toLowerCase())));}
function packageTable(){const packs=edtsFiltered();if(!packs.length)return '<div class="no-results">No hay paquetes que cumplan los filtros.</div>';return `<div class="table-scroller"><table><thead><tr><th>EDT</th><th>Entregable</th><th>Cuenta</th><th>BAC</th><th>Semanas</th><th>Gate</th><th>Riesgo</th></tr></thead><tbody>${packs.map(p=>`<tr><td><button class="table-button" data-package="${p.id}">${p.id}</button></td><td>${esc(p.name)}</td><td>${p.account}</td><td class="tdnum">${money(p.bac)}</td><td>S${p.weekStart}–S${p.weekEnd}</td><td><span class="tag">${p.gate}</span></td><td><button class="table-button" data-risk="${p.risk}">${p.risk}</button></td></tr>`).join('')}</tbody></table></div><p class="footnote">${packs.length} de 26 entregables · BAC filtrado ${money(packs.reduce((a,b)=>a+b.bac,0))} · la asignación de pesos es una propuesta de planeación.</p>`;}
function packageDetail(){const p=D.packages.find(x=>x.id===S.selectedPackage)||D.packages[0];const pvP3=p.pvByPhase.slice(0,4).reduce((a,b)=>a+b,0),evB=p.evRule==='0/100'&&p.evFactorB<1?0:pvP3*p.evFactorB,evC=p.evRule==='0/100'&&p.evFactorC<1?0:pvP3*p.evFactorC;return `<div class="panel-heading"><div><h3>${p.id} · ${esc(p.name)}</h3><p>Cuenta ${p.account} · ${p.gate} · Riesgo ${p.risk}</p></div>${tags.source}</div><div class="detail-list"><dt>BAC paquete</dt><dd>${money(p.bac)} (${pct(p.weight,0)} de la cuenta)</dd><dt>Fases</dt><dd>P${p.phaseStart}–P${p.phaseEnd} · Semanas S${p.weekStart}–S${p.weekEnd}</dd><dt>Responsable</dt><dd>${esc(p.owner)} <span class="muted">(propuesto)</span></dd><dt>Dependencia</dt><dd>${esc(p.depends)}</dd><dt>Regla EV</dt><dd>${esc(p.evRule)}</dd><dt>Aceptación</dt><dd>${esc(p.accept)}</dd><dt>Riesgo</dt><dd>${p.risk} · <button class="nav-link-inline" data-risk="${p.risk}">Ver riesgo →</button></dd></div><div class="small-cards" style="margin-top:18px"><div class="small-card"><small>CASO B · CORTE P3</small><strong>EV ${money(evB)}</strong><p>Factor ${pct(p.evFactorB,0)} · ${p.correctiveHoursB} h correctivas</p></div><div class="small-card"><small>CASO C · CORTE P3</small><strong>EV ${money(evC)}</strong><p>Factor ${pct(p.evFactorC,0)} · ${p.correctiveHoursC} h correctivas</p></div></div><div class="source-line" style="margin-top:18px"><b>PV por fase del paquete:</b><div class="bar-track" style="height:14px;margin-top:11px;display:flex;gap:1px">${p.pvByPhase.map((v,i)=>`<div title="P${i}: ${money(v)}" style="width:${v/p.bac*100}%;background:${['#277c85','#419aa0','#5cb6b1','#7fc8b3','#a1d8bd','#c3e6ca','#d5e8e6'][i]};height:100%"></div>`).join('')}</div><small>De P0 a P6 · suma ${money(p.pvByPhase.reduce((a,b)=>a+b,0))}</small></div>`;}
function gantt(){const packs=edtsFiltered();return `<div class="gantt-scroll"><div class="gantt"><div class="gantt-head"><span style="text-align:left">PAQUETE · SEMANAS</span>${Array.from({length:21},(_,i)=>`<span>${i+1}</span>`).join('')}</div>${packs.map(p=>`<div class="gantt-row ${p.id===S.selectedPackage?'highlight':''}"><button type="button" class="table-button gantt-label" data-package="${p.id}" title="${esc(p.name)}">${p.id} · ${esc(p.name)}</button>${Array.from({length:21},(_,i)=>{const wk=i+1,on=wk>=p.weekStart&&wk<=p.weekEnd;return `<span title="${p.id} · S${wk}" class="gantt-cell ${on?(wk===p.weekEnd?'end':'on'):wk===21?'buffer':''}"></span>`}).join('')}</div>`).join('')}</div></div><p class="footnote">S21 es exclusivamente un buffer de fecha (sin trabajo programado ni EV). Dependencias FS/SS son propuestas condicionadas a aceptación y acceso a recursos.</p>`;}
function edts(){return `${sectionTop('03 · ALCANCE Y CONTROL','EDT, costos y calendario','El plan desagrega las ocho cuentas presupuestarias en 26 paquetes verificables. Selecciona una cuenta, un gate o un paquete para seguir la relación entre presupuesto, evidencia, responsabilidad y riesgo.','edtTitle')}
 <div class="metric-grid">${metric('Paquetes verificables','26','Regla del 100 %')}${metric('Cuentas de control','8','Directas e indirectas')}${metric('BAC distribuido',money(D.bac),'PV/EV solo sobre trabajo')}${metric('Buffer de calendario','S21','Sin actividad ni EV')}</div>
 <section class="surface mb18"><div class="panel-heading"><div><h3>Puente presupuestal</h3><p>El valor ganado usa BAC sin EMV; la inversión total incorpora reserva una sola vez.</p></div>${tags.source}</div><div class="result-grid"><div class="result-stat"><small>Directos</small><strong>${moneyM(D.direct)}</strong><span>6 cuentas</span></div><div class="result-stat"><small>Indirectos</small><strong>${moneyM(D.indirect)}</strong><span>2 cuentas</span></div><div class="result-stat"><small>EMV residual</small><strong>${moneyM(D.reserve)}</strong><span>P7 · No acreditable</span></div></div><div class="source-line"><b>Control:</b> ${money(D.direct)} + ${money(D.indirect)} = ${money(D.bac)} (trabajo). + ${money(D.reserve)} = ${money(D.investment)} (techo). La EMV no es una novena cuenta de valor ganado.</div></section>
 <div class="columns2 mb18"><section class="surface"><div class="panel-heading"><div><h3>PV frente a distribución de inversión</h3><p>Fases P0–P7, no equivalentes a los 36 meses financieros</p></div>${tags.source}</div>${pvChart()}<div class="notice info" style="margin-top:12px">PV acumulado al cierre P3: <b>${money(D.evmCases[0].pv)}</b>. La inversión por fases puede diferir del PV por adelantos, pagos y reserva; no son la misma curva.</div></section><section class="surface"><div class="panel-heading"><div><h3>Presupuesto por cuenta</h3><p>Selecciona para filtrar el diccionario de trabajo</p></div></div>${D.accounts.map(a=>`<button type="button" data-account="${a.id}" style="width:100%;border:0;border-bottom:1px solid #edf1f2;background:${S.account===a.id?'#effaf7':'transparent'};text-align:left;padding:8px 4px;display:flex;align-items:center;justify-content:space-between;font-size:12px;gap:10px"><span><b style="color:var(--teal)">${a.id}</b> · ${esc(a.name)}</span><b style="white-space:nowrap">${moneyM(a.bac)}</b></button>`).join('')}<p class="footnote">La distribución de los 26 paquetes es una hipótesis de planeación del libro, no cotización bottom-up definitiva.</p></section></div>
 <section class="surface mb18" id="packages"><div class="panel-heading"><div><h3>Diccionario EDT · 26 paquetes</h3><p>Todos los montos, criterios de aceptación, dueños, fechas y dependencias provienen de 02_EDT_26.</p></div><button class="secondary-btn compact" data-export="edt">↓ Exportar 26 paquetes</button></div><div class="toolbar"><input type="search" id="packageSearch" value="${esc(S.packageSearch)}" placeholder="Buscar nombre, código, responsable o riesgo" aria-label="Buscar paquetes"><select id="accountFilter" aria-label="Filtrar por cuenta"><option value="all">Todas las cuentas</option>${D.accounts.map(a=>`<option value="${a.id}" ${S.account===a.id?'selected':''}>${a.id} · ${esc(a.name)}</option>`).join('')}</select><select id="gateFilter" aria-label="Filtrar por gate"><option value="all">Todos los gates</option>${D.gates.map(g=>`<option ${S.gateFilter===g.id?'selected':''}>${g.id}</option>`).join('')}</select><button class="secondary-btn compact" data-clear-edt>Limpiar</button></div><div id="packageTableHost">${packageTable()}</div></section>
 <div class="detail-split mb18"><section class="surface" id="packageDetailHost">${packageDetail()}</section><section class="surface"><div class="panel-heading"><div><h3>¿Cuándo sucede el trabajo?</h3><p>Gantt semanal del filtro activo</p></div>${tags.source}</div><div id="ganttHost">${gantt()}</div></section></div>
 ${notice('Una fecha de Gantt indica una ventana de planeación; no convierte el paquete en completado. Para reconocer EV deben cumplirse los criterios de aceptación, en especial en paquetes con regla 0/100.','info')}`;}
function riskHeat(){const map=new Map();for(const r of D.risks){const k=r.p+'-'+r.impact;if(!map.has(k))map.set(k,[]);map.get(k).push(r);}return `<div class="risk-axes"><span>Probabilidad ↑ (5 a 1)</span><span>Impacto → (1 a 5)</span></div><div class="riskgrid">${[5,4,3,2,1].flatMap(p=>[1,2,3,4,5].map(i=>{const score=p*i,cl=score>=20?'critical':score>=15?'high':score>=8?'medium':'';return `<div class="riskcell ${cl}"><b>${p} × ${i} = ${score}</b>${(map.get(p+'-'+i)||[]).map(r=>`<button data-risk="${r.id}" type="button">${r.id}</button>`).join('')}</div>`})).join('')}</div><p class="footnote">P×I prioriza exposición inherente, no equivale a pérdida financiera ni probabilidad real. Los tres eventos de oportunidad se señalan con +.</p>`;}
function selectedRisk(){const r=D.risks.find(x=>x.id===S.selectedRisk)||D.risks[0];const packages=D.packages.filter(p=>p.risk===r.id);return `<div class="panel-heading"><div><h3>${r.id} · ${esc(r.name)}</h3><p>${r.group} · Hipótesis ${r.hypothesis} · ${r.gates}</p></div><span class="tag ${r.level==='Crítico'?'poor':r.level==='Veto'?'veto':'medium'}">${r.level==='Oportunidad'?'OPORTUNIDAD':r.level} · ${r.p*r.impact}</span></div><div class="detail-list"><dt>Prioridad inherente</dt><dd>${r.p} × ${r.impact} = ${r.p*r.impact}</dd><dt>Disparador</dt><dd>${esc(r.trigger||'Ver condiciones de aplicación por riesgo')}</dd><dt>Respuesta</dt><dd>${esc(r.action||r.response)}</dd><dt>Cuenta / gate</dt><dd>${r.gates}</dd><dt>EDT vinculada</dt><dd>${packages.length?packages.map(p=>`<button class="nav-link-inline" data-package="${p.id}">${p.id}</button>`).join(' · '):'No posee asignación primaria en el diccionario de 26 paquetes'}</dd></div><div class="notice info" style="margin-top:16px"><b>Conexión causal propuesta:</b> el riesgo debe verificarse en su evidencia, costo, gate y eventual demora de beneficios. No se asigna automáticamente un VPN por seleccionar un riesgo.</div><div class="row-buttons" style="margin-top:13px"><button class="secondary-btn compact" data-risk-test="B">Ensayar EVM B</button><button class="secondary-btn compact" data-risk-test="C">Ensayar EVM C</button></div>`;}
function riskTable(){const data=D.risks.filter(r=>(S.riskGroup==='Todos'||r.group===S.riskGroup)&&(r.id+' '+r.name+' '+r.hypothesis).toLowerCase().includes(S.riskSearch.toLowerCase()));return `<div class="table-scroller"><table><thead><tr><th>Riesgo</th><th>Familia</th><th>Evento</th><th>P/I</th><th>Prioridad</th><th>EDT</th></tr></thead><tbody>${data.map(r=>`<tr><td><button class="table-button" data-risk="${r.id}">${r.id}</button></td><td>${r.group}</td><td>${esc(r.name)}</td><td>${r.p} × ${r.impact}</td><td><span class="tag ${r.level==='Crítico'?'poor':r.level==='Veto'?'veto':r.level==='Oportunidad'?'good':'medium'}">${r.level}</span></td><td>${r.packages.join(', ')||'—'}</td></tr>`).join('')}</tbody></table></div><p class="footnote">${data.length} de 18 eventos · respuestas y disparadores del modelo de riesgo S5/S6.</p>`;}
function risks(){return `${sectionTop('04 · INCERTIDUMBRE','Riesgos y puertas de decisión','La matriz identifica exposiciones; la EDT indica dónde se materializan; EVM muestra el efecto de las desviaciones; el VPN exige recalcular el valor. Seleccionar una celda no implica que el evento ocurrió.','riesgosTitle')}
 <div class="metric-grid">${metric('Riesgos y oportunidades','18','15 amenazas y 3 oportunidades')}${metric('Críticos inherentes','3','RT1 · RO1 · RI3')}${metric('Vetos técnicos','RI4 / RE1','Seguridad y cumplimiento')}${metric('Gates','G0–G3','No se liberan por CPI')}</div>
 <div class="columns2 mb18"><section class="surface"><div class="panel-heading"><div><h3>Matriz de prioridad P × I</h3><p>Selecciona el código para trazar la respuesta</p></div>${tags.source}</div>${riskHeat()}</section><section class="surface" id="riskDetailHost">${selectedRisk()}</section></div>
 <section class="surface mb18"><div class="panel-heading"><div><h3>Cadena de riesgos que se refuerzan</h3><p>Correlación interpretativa de la Semana 5</p></div>${tags.interpret}</div><div class="cause-flow"><div class="node"><small>RI6</small><strong>WIP de cambio</strong></div><div class="node"><small>RI2</small><strong>Formación insuficiente</strong></div><div class="node"><small>RO1</small><strong>Adopción baja</strong></div><div class="node"><small>RT1</small><strong>Datos incompletos</strong></div><div class="node"><small>RI3</small><strong>Ahorro sin validar</strong></div></div><p class="footnote">La flecha significa una posible dependencia cualitativa, no una probabilidad condicional ni un costo esperado demostrado.</p></section>
 <section class="surface mb18"><div class="panel-heading"><div><h3>Registro de riesgo consultable</h3><p>Incluye eventos que no son primarios en la EDT pero siguen siendo relevantes al gobierno del proyecto.</p></div><button class="secondary-btn compact" data-export="risks">↓ Registro CSV</button></div><div class="toolbar"><select id="riskGroup"><option>Todos</option>${['Técnico','Externo','Organizacional','Implementación'].map(x=>`<option ${S.riskGroup===x?'selected':''}>${x}</option>`).join('')}</select><input id="riskSearch" type="search" aria-label="Buscar riesgo" value="${esc(S.riskSearch)}" placeholder="Código, evento o hipótesis"></div><div id="riskTableHost">${riskTable()}</div></section>
 <section class="surface mb18"><div class="panel-heading"><div><h3>G0 → G3: detener, corregir o continuar</h3><p>Hitos propuestos, sujetos a evidencia y autorizaciones</p></div>${tags.source}</div><div class="gate-timeline">${D.gates.map(g=>`<div class="gate-card"><small>${g.id} · ${g.window}</small><strong>${g.name}</strong><p>${esc(g.requirement)}</p><b>Si falla:</b><p>${esc(g.block)}</p></div>`).join('')}</div></section>
 ${notice('Cynefin: riesgos claros se gestionan con estándares y datos; complicados requieren análisis experto; complejos exigen experimentación segura; caóticos implican contención inmediata. La clasificación orienta la respuesta y no predice ocurrencia.','info')}`;}
function actorTable(){return `<div class="table-scroller"><table><thead><tr><th>Código</th><th>Interesado</th><th>Poder / interés</th><th>${S.actorVersion==='v0'?'E documental':'Enganche E (1–5)'}</th><th>Estado</th></tr></thead><tbody>${D.actors.filter(a=>S.actorVersion!=='v0'||a.id!=='A13').map(a=>`<tr><td>${a.id}</td><td>${esc(a.name)}</td><td>${a.power} / ${a.interest}</td><td>${S.actorVersion==='v0'?'N/D':S.actorVersion==='v1'?a.eV1:a.eV2}</td><td><span class="tag ${S.actorVersion==='v2'?'medium':''}">${S.actorVersion==='v0'?'Sin medición':S.actorVersion==='v1'?'Estimación':'Meta propuesta'}</span></td></tr>`).join('')}</tbody></table></div><p class="footnote">V0 no cuenta con índice medido: N/D no equivale a cero. V1 es estimación de vinculación; V2 representa metas E* por concretar. No alteran directamente el VPN financiero.</p>`;}
/* Profundización histórica S1–S6. Recuperación interpretativa del Artifact previo;
   V0 sin medición, V1 estimado, V2 meta; escenarios financieros y EVM independientes. */
const ARCH=D.archive;
function archiveActors(v=S.actorVersion,h=null){
 return D.actors.filter(a=>(v!=='v0'||a.id!=='A13')&&(!h||ARCH.actorInfo.find(x=>x.id===a.id)?.h.includes(h)));
}
function archiveCoverage(v,h=null){
 if(v==='v0')return null;
 let denom=0,penalty=0;
 for(const a of archiveActors(v,h)){
  const info=ARCH.actorInfo.find(x=>x.id===a.id);if(!info)continue;
  const w=a.power*a.interest;
  denom+=w;penalty+=w*Math.max(0,info.required-(v==='v1'?a.eV1:a.eV2));
 }
 return denom?100*(1-penalty/(3*denom)):null;
}
function archiveGap(a,v){if(v==='v0')return null;const info=ARCH.actorInfo.find(x=>x.id===a.id);return Math.max(0,info.required-(v==='v1'?a.eV1:a.eV2));}
function archivePct(v){return v==null?'N/D':dec(v,1)+' %';}
function archiveJump(label,tab){return `<button type="button" class="secondary-btn compact" data-archive-go="${tab}">${label}</button>`;}
function archiveNav(){const tabs=[['evolucion','01','Modelo original → Diagnóstico → Meta'],['estrategia','02','Entorno, competencia y Canvas'],['gestion','03','BSC, OKR y control de riesgos']];return `<div class="archive-subtabs" role="group" aria-label="Análisis anteriores agrupados">${tabs.map(([id,n,t])=>`<button type="button" class="archive-subtab ${S.archiveTab===id?'active':''}" data-archive-tab="${id}" aria-pressed="${S.archiveTab===id}"><span>${n}</span>${t}</button>`).join('')}</div>`;}
function archiveVersionPanel(){const stages=[['v0','Modelo original','Canvas de PI1 · 12 actores','No hay nivel E registrado'],['v1','Diagnóstico','13 actores · condición estimada','Brechas y supuestos por validar'],['v2','Meta','13 actores · propuesta de vinculación','No equivale a implementación']];return `<div class="archive-version-grid">${stages.map(([v,t,sub,bottom])=>`<button type="button" class="archive-version ${S.actorVersion===v?'active':''}" data-actorversion="${v}"><small>${v.toUpperCase()} · ${esc(t)}</small><strong>${v==='v0'?'N/D':archivePct(archiveCoverage(v))}</strong><span>${esc(sub)}</span><em>${esc(bottom)}</em></button>`).join('')}</div>`;}
function archiveEvolutionChart(){
 const rows=ARCH.hypothesisDetail.map(h=>{
  const a=archiveCoverage('v1',h.id),b=archiveCoverage('v2',h.id);
  return `<button type="button" class="archive-hyp-row ${S.archiveH===h.id?'selected':''}" data-archive-h="${h.id}"><span><b>${h.id}</b> · ${esc(h.title)}</span><span class="archive-bar-pair"><i class="archive-bar one" style="width:${a.toFixed(1)}%"></i><i class="archive-bar two" style="width:${b.toFixed(1)}%"></i></span><span class="archive-pair-num">${archivePct(a)} <b>→</b> ${archivePct(b)}</span></button>`;
 });return `<div class="archive-legend"><span><i class="dot v1"></i>Diagnóstico V1</span><span><i class="dot v2"></i>Meta V2 (no ejecutada)</span></div><div class="archive-hyp-grid">${rows.join('')}</div>`;
}
function archiveHypDetail(){const h=ARCH.hypothesisDetail.find(x=>x.id===S.archiveH)||ARCH.hypothesisDetail[0];
 const a=archiveCoverage('v1',h.id),b=archiveCoverage('v2',h.id);
 const actors=archiveActors('v1',h.id),linkedRisks=D.risks.filter(r=>r.hypothesis===h.id),linkedPacks=D.packages.filter(p=>linkedRisks.some(r=>r.id===p.risk)).slice(0,8);
 return `<article class="archive-detail"><div class="panel-heading"><div><span class="eyebrow">HIPÓTESIS ${h.id} · Trazabilidad causal</span><h3>${esc(h.title)}</h3></div>${tags.interpret}</div>
 <div class="archive-summary-grid"><div><small>V0 · documento</small><b>N/D</b></div><div><small>V1 · diagnóstico</small><b>${archivePct(a)} · ${h.v1==='AC'?'Apoyo cualitativo':'Débil / sin validar'}</b></div><div><small>V2 · meta</small><b>${archivePct(b)} · Validación condicionada</b></div></div>
 <div class="archive-evidence-list"><p><b>Información de partida:</b> ${esc(h.evidence)}</p><p><b>Brecha detectada:</b> ${esc(h.weakness)}</p><p><b>Acción propuesta:</b> ${esc(h.action)}</p><p><b>Evidencia para cerrar:</b> ${esc(h.test)}</p></div>
 <p class="archive-linkline"><b>Actores vinculados:</b> ${actors.map(a=>`<button class="table-button" data-archive-actor="${a.id}">${a.id}</button>`).join(' ')}</p>
 <p class="archive-linkline"><b>Riesgos relacionados:</b> ${linkedRisks.length?linkedRisks.map(r=>`<button class="table-button" data-risk="${r.id}">${r.id}</button>`).join(' '):'Sin vínculo directo en el registro'}</p>
 <p class="archive-linkline"><b>Paquetes EDT trazables por riesgo:</b> ${linkedPacks.length?linkedPacks.map(p=>`<button class="table-button" data-package="${p.id}">${p.id}</button>`).join(' '):'Sin relación unívoca identificada'}</p>
 <p class="footnote">Cobertura calculada con la fórmula original: 100 × [1 − Σ(poder × interés × brecha E)/(3 × Σ poder × interés)]. Es un índice de vinculación estimada, no validación técnica ni probabilidad de éxito.</p></article>`;
}
function archiveActorTable(){const v=S.actorVersion,rows=archiveActors(v);return `<div class="panel-heading"><div><h3>Matriz poder–interés y vinculación por interesado</h3><p>Selecciona un actor para conocer por qué cambia entre el diagnóstico y la meta.</p></div></div>
 <div class="table-scroller"><table><thead><tr><th>Actor</th><th>P/I</th><th>E requerida</th><th>V0</th><th>V1 estimada</th><th>V2 meta</th><th>Brecha ${v.toUpperCase()}</th></tr></thead><tbody>${rows.map(a=>{const info=ARCH.actorInfo.find(x=>x.id===a.id);const g=archiveGap(a,v);return `<tr class="${S.archiveActor===a.id?'archive-selected':''}"><td><button class="table-button" data-archive-actor="${a.id}">${a.id}</button> · ${esc(a.name)}</td><td>${a.power}/${a.interest}</td><td>${info.required}</td><td>N/D${a.id==='A13'?'*':''}</td><td>${a.eV1}</td><td>${a.eV2}</td><td>${g==null?'N/D':g}</td></tr>`;}).join('')}</tbody></table></div>
 <p class="footnote">* A13 fue agregado en PI2. Para V0 se conservan solo los 12 actores originales; no se inventa E histórico.</p>${archiveActorDetail()}`;}
function archiveActorDetail(){const a=D.actors.find(a=>a.id===S.archiveActor)||D.actors.find(a=>a.id==='A08'),i=ARCH.actorInfo.find(x=>x.id===a.id);return `<div class="archive-actor-detail"><span class="eyebrow">INTERESADO ${a.id} · ${esc(i.role)}</span><h3>${esc(a.name)}</h3><div class="archive-summary-grid"><div><small>Poder / interés</small><b>${a.power} / ${a.interest}</b></div><div><small>Diagnóstico V1</small><b>E=${a.eV1} / requerida=${i.required}</b></div><div><small>Meta V2</small><b>E*=${a.eV2} / brecha=${Math.max(0,i.required-a.eV2)}</b></div></div><p><b>Estado de evidencia:</b> ${esc(i.source)}</p><p><b>Intervención:</b> ${esc(i.action)}</p><p><b>Prueba de cierre:</b> ${esc(i.proof)}</p><p><b>Hipótesis:</b> ${i.h.map(h=>`<button class="table-button" data-archive-h="${h}">${h}</button>`).join(' ')}</p></div>`;}
function evolutionSection(){const v=S.actorVersion,selectedCoverage=archiveCoverage(v),delta=archiveCoverage('v2')-archiveCoverage('v1');return `
 <div class="archive-head"><div><h2>Modelo original → Diagnóstico → Meta</h2><p>La línea evolutiva atraviesa Canvas, actores, hipótesis y gates. V0 es documental; V1 estima vinculación; V2 es una meta que debe demostrarse.</p></div>${tags.source}</div>
 ${archiveVersionPanel()}
 <div class="archive-keyline">${v==='v0'?'No se calcula una cobertura histórica: PI1 no registró E por interesado.':v==='v1'?'Se registran niveles E estimados, sujetos a validación con interesados.':'Los E* de la propuesta permiten estimar la mejora, pero todavía NO son resultados del piloto.'} La distancia V1 → V2 es <strong>+${dec(delta,1)} puntos de cobertura ponderada propuesta</strong>, no mejora observada.</div>
 <div class="columns2 mb18"><section class="surface"><div class="panel-heading"><div><h3>Solidez por hipótesis</h3><p>H1–H6 en las dos versiones con nivel de vinculación modelado.</p></div></div>${archiveEvolutionChart()}</section><section class="surface"><div class="panel-heading"><div><h3>Qué cambia en la decisión</h3></div></div><div class="archive-narrative"><p><b>V0 · modelo original:</b> describe el negocio y 12 actores. Permite discutir la estrategia, pero no medir adhesión retrospectiva.</p><p><b>V1 · diagnóstico:</b> las brechas E y las posturas sin determinar obligan a validar RACI, participación de Producción, fuentes y VOC antes de liberar gates.</p><p><b>V2 · meta:</b> propone involucrar responsables y elevar E*, de forma condicional. El valor ganado solo se acredita al aceptar entregables y el VPN solo se modifica con supuestos económicos explícitos.</p><p><b>Regla de decisión:</b> pasar de V1 a V2 no autoriza por sí mismo el piloto ni mejora automáticamente EVM o rentabilidad.</p></div><button type="button" class="secondary-btn compact" data-archive-go="gestion">Ver evidencia KPI / OKR →</button></section></div>
 ${archiveHypDetail()}
 <section class="surface mb18">${archiveActorTable()}</section>
 ${notice('<b>Separación metodológica:</b> V0/V1/V2 son versiones del diagnóstico estratégico y de interesados; conservador/base/favorable son escenarios de flujos; A/B/C son pruebas de ejecución EVM. Pueden relacionarse causalmente mediante hipótesis y evidencia, pero no equipararse.', 'info')}`;}
function archiveFiveDots(n){return `<span class="archive-score">${Array.from({length:5},(_,i)=>`<i class="${i<n?'filled':''}"></i>`).join('')}<b>${n}/5</b></span>`;}
function archiveCanvas(){return `<div class="archive-canvas-grid">${ARCH.canvas.map(c=>`<article class="archive-canvas-card"><small>CANVAS · ${c.id.toUpperCase()}</small><h4>${esc(c.name)}</h4><p><b>Original · V0:</b> ${esc(c.v0)}</p><p><b>Meta · V2:</b> ${esc(c.v2)}</p><div class="archive-diff">${esc(c.diff)}</div></article>`).join('')}</div><p class="footnote">El diagnóstico V1 no fue una tercera versión textual independiente del Canvas: su principal aporte fue identificar brechas de interesados, evidencia y factibilidad. Por eso no se le atribuyen bloques nuevos.</p>`;}
function strategicSection(){const selected=ARCH.delta.find(x=>x.id===S.archiveDelta)||ARCH.delta[1],weights=ARCH.deltaWeights,score=x=>(x.technical*weights.technical+x.customer*weights.customer+x.system*weights.system)/100;return `
 <div class="archive-head"><div><h2>Entorno, competencia y propuesta de valor</h2><p>De las señales externas a la orientación estratégica de NEXO-INNOVA. Cada herramienta aporta una pregunta distinta, conectada con hipótesis, gates y evidencia.</p></div>${tags.interpret}</div>
 <section class="surface mb18"><div class="panel-heading"><div><h3>PESTEL · factores de contexto</h3><p>Importancia cualitativa del Artifact de Semana 2; no son probabilidades ni impactos en COP.</p></div><span class="tag">6 factores</span></div><div class="archive-factor-grid">${ARCH.pestel.map(p=>`<article class="archive-factor"><div class="archive-factor-title"><span class="archive-factor-letter">${p.id}</span><h4>${esc(p.name)}</h4>${archiveFiveDots(p.score)}</div><strong>${esc(p.signal)}</strong><p>${esc(p.impact)}</p><small>Acción: ${esc(p.response)}</small><div class="archive-inline">${p.h.map(h=>`<button class="table-button" data-archive-h="${h}">${h}</button>`).join(' ')}</div></article>`).join('')}</div></section>
 <section class="surface mb18"><div class="panel-heading"><div><h3>Cinco fuerzas de Porter</h3><p>Convierten presiones competitivas en decisiones de selección de oportunidades.</p></div></div><div class="archive-forces">${ARCH.porter.map(p=>`<article><div><strong>${esc(p.name)}</strong><p>${esc(p.mechanism)}</p><small>Respuesta: ${esc(p.action)}</small><div class="archive-inline">${p.h.map(h=>`<button class="table-button" data-archive-h="${h}">${h}</button>`).join(' ')}</div></div>${archiveFiveDots(p.score)}</article>`).join('')}</div></section>
 <section class="surface mb18"><div class="panel-heading"><div><h3>Modelo Delta · estrategia a contrastar</h3><p>Escoring ilustrativo con pesos técnicos 30 %, cliente 55 % y sistema 15 %. No es una ventaja competitiva validada.</p></div></div><div class="archive-strategy-grid">${ARCH.delta.map(d=>`<button type="button" class="archive-strategy ${S.archiveDelta===d.id?'active':''}" data-archive-delta="${d.id}"><small>${esc(d.name)}</small><strong>${dec(score(d),2)} / 5</strong><span>Índice de preferencia modelado</span></button>`).join('')}</div><div class="archive-strategy-detail"><b>${esc(selected.name)}</b><p>${esc(selected.desc)}</p><p><b>Qué falta comprobar:</b> ${esc(selected.validation)}</p><p><b>Conexión:</b> PESTEL/Porter → VOC y factibilidad → selección de oportunidades → <button class="table-button" data-archive-h="H4">H4</button> / <button class="table-button" data-archive-h="H6">H6</button> → gate G1.</p></div></section>
 <section class="surface mb18"><div class="panel-heading"><div><h3>Canvas original frente a la meta</h3><p>Nueve bloques, evolución documentada e interpretación de qué se hace más verificable.</p></div></div>${archiveCanvas()}</section>
 ${notice('La presión externa no se traduce automáticamente en una reducción del VPN. Para ello se necesita definir un supuesto sobre demanda, adopción, costo o fecha, y comprobar su efecto en los flujos.', 'info')}`;}
function archiveBsc(){const groups=['Aprendizaje','Procesos','Clientes','Financiera'];return groups.map(g=>`<div class="archive-kpi-group"><div class="archive-kpi-header"><b>${g}</b><small>${D.kpis.filter(k=>k.perspective===g).length} indicadores</small></div><div class="table-scroller"><table><thead><tr><th>Código</th><th>Indicador</th><th>Fórmula / criterio</th><th>Meta académica</th><th>Hipótesis</th></tr></thead><tbody>${D.kpis.filter(k=>k.perspective===g).map(k=>`<tr><td>${k.id}</td><td>${esc(k.name)}</td><td>${esc(k.formula)}</td><td>${esc(k.target)}</td><td>${esc(k.hypotheses)}</td></tr>`).join('')}</tbody></table></div></div>`).join('');}
function archiveOkr(){return `<div class="archive-okr-grid">${ARCH.okrDetails.map(o=>`<article class="archive-okr-card"><span class="eyebrow">${o.id} · ${esc(o.p)}</span><h4>${esc(o.title)}</h4>${o.krs.map(([k,t,metric,proof])=>`<div class="archive-kr"><b>${k}</b><div><strong>${esc(t)}</strong><small>KPI ${esc(metric)} · Verificar: ${esc(proof)}</small></div></div>`).join('')}</article>`).join('')}</div>`;}
function archiveCynefin(){return `<div class="archive-cynefin-grid">${ARCH.cynefin.map(c=>`<article><span class="eyebrow">${esc(c.id)} · ${esc(c.gate)}</span><h4>${esc(c.logic)}</h4><p>${esc(c.signal)}</p><small><b>Ejemplos de riesgo:</b> ${esc(c.risks)}</small><p><b>Intervención:</b> ${esc(c.action)}</p></article>`).join('')}</div>`;}
function archiveRiskChains(){return `<div class="archive-chain-list">${ARCH.riskLinks.map(([from,to,what])=>`<div class="archive-chain-row"><button class="table-button" data-risk="${from}">${from}</button><span>→</span><button class="table-button" data-risk="${to}">${to}</button><p>${esc(what)}</p></div>`).join('')}</div>`;}
function archiveTrail(){return `<div class="archive-timeline">${D.strategic.map(t=>`<article><span>${esc(t.id)}</span><div><b>${esc(t.name)}</b><p>${esc(t.summary)}</p><small>${esc(t.thread)}</small></div><strong>${esc(t.target)}</strong></article>`).join('')}</div>`;}
function managementSection(){return `<div class="archive-head"><div><h2>Medición, aprendizaje y riesgo integrado</h2><p>Desde una hipótesis estratégica hasta su evidencia: BSC → resultados clave → riesgo → paquete EDT → gates → valoración financiera.</p></div>${tags.interpret}</div>
 <section class="surface mb18"><div class="panel-heading"><div><h3>BSC · diez KPI con ficha de interpretación</h3><p>No son resultados observados. Las fichas requieren datos, fuente, frecuencia, responsable y línea base antes de declarar desempeño.</p></div></div>${archiveBsc()}</section>
 <section class="surface mb18"><div class="panel-heading"><div><h3>OKR · cuatro objetivos y doce KR</h3><p>Las metas propuestas orientan el piloto; ningún KR se marca como cumplido sin evidencia.</p></div></div>${archiveOkr()}</section>
 <div class="columns2 mb18"><section class="surface"><div class="panel-heading"><div><h3>Cynefin extendido</h3><p>El tipo de incertidumbre cambia la respuesta apropiada.</p></div></div>${archiveCynefin()}</section><section class="surface"><div class="panel-heading"><div><h3>Correlaciones entre riesgos</h3><p>Red interpretativa: no se infieren probabilidades condicionales ni P/I residual.</p></div></div>${archiveRiskChains()}<button class="secondary-btn compact" type="button" data-go="riesgos">Ir a matriz P×I y gates →</button></section></div>
 <section class="surface mb18"><div class="panel-heading"><div><h3>Historia acumulada y decisión que habilita</h3><p>El contenido de S1–S6 se conserva, organizado por su utilidad para decidir.</p></div></div>${archiveTrail()}</section>
 <section class="surface mb18"><div class="panel-heading"><div><h3>Integración hasta la Semana 6</h3><p>Leer cada decisión en la secuencia verificable.</p></div></div><div class="archive-decision-chain"><div><small>01</small><strong>Canvas / entorno / actores</strong><p>Identificar por qué y con quién.</p></div><div><small>02</small><strong>H1–H6 + BSC / OKR</strong><p>Definir qué se debe probar.</p></div><div><small>03</small><strong>EDT + riesgos + gates</strong><p>Asignar entregable, dependencia y riesgo.</p></div><div><small>04</small><strong>PV / EV / AC</strong><p>Acreditar resultados sin confundir gasto con aceptación.</p></div><div><small>05</small><strong>VPN / continuidad</strong><p>Decidir con beneficios defendibles y contingencia conciliada.</p></div></div><div class="archive-bottom-actions"><button type="button" class="secondary-btn compact" data-go="edt">Ver los 26 paquetes EDT</button><button type="button" class="primary-btn compact" data-go="decisiones">Comparar escenarios EVM y VPN</button></div></section>
 ${notice('<b>Principio de gobierno:</b> las metas del BSC/OKR, un E* alto o una exposición P×I baja no sustituyen la aceptación de entregables, el control de acceso, la factibilidad ni un VPN verificado.', 'info')}`;}
function history(){const panels={evolucion:evolutionSection,estrategia:strategicSection,gestion:managementSection};return `${sectionTop('05 · LECTURA INTEGRADA','Conocimiento y evolución del proyecto','Profundización recuperada de las semanas 1 a 5 y conectada con la Semana 6. Tres rutas, sin volver a las veinticinco secciones anteriores.','trazabilidadTitle')}${archiveNav()}<div class="archive-content">${(panels[S.archiveTab]||panels.evolucion)()}</div>`;}

function archiveQuick(){return `<section class="surface archive-quick"><div class="panel-heading"><div><h3>El modelo estratégico también tiene tres versiones</h3><p>Modelo original (V0) → Diagnóstico (V1) → Meta (V2). No son los escenarios económicos ni los estados EVM.</p></div><span class="data-tag interpret">S1 · comparación histórica</span></div><div class="archive-quick-grid">${[["v0","Modelo original","N/D","12 actores · sin E histórico"],["v1","Diagnóstico",archivePct(archiveCoverage("v1")),"13 actores · E estimada"],["v2","Meta",archivePct(archiveCoverage("v2")),"13 actores · E* propuesta"]].map(([id,name,value,subtitle])=>`<button type="button" data-archive-go="evolucion" data-select-version="${id}"><strong>${name}</strong><b>${value}</b><span>${subtitle}</span></button>`).join("")}</div><p class="footnote">La cobertura mide brecha ponderada de vinculación, no avance del piloto. Selecciona una versión para revisar la metodología y la evidencia exigida.</p></section>`;}
function renderCurrent(){const lookup={panorama:['panoramaHost',panorama],decisiones:['decisionesHost',decisions],edt:['edtHost',edts],riesgos:['riesgosHost',risks],trazabilidad:['trazabilidadHost',history]};const pair=lookup[S.tab];const host=$('#'+pair[0]);if(host)host.innerHTML=pair[1]();}
function updateSimOutputs(){if(S.tab!=='decisiones')return;const e=getEVM(),f=financialResult(),rec=reportRecommendation(f);
 const update=(id,html)=>{const el=$('#'+id);if(el)el.innerHTML=html;};
 update('simMetrics',simMetrics(e,f));update('scenarios3',threeFinanceCards());update('financeReading',financeReading(f));update('financeMetrics',financeMetrics(f));update('recommendation',notice(`<b>${rec.title}</b><p style="margin:6px 0 0">${rec.text}</p>`,rec.type));update('chainHost',chainFlow(f));update('matrixHost',scenarioMatrix());
}
function download(name,content,type='text/plain;charset=utf-8'){const url=URL.createObjectURL(new Blob([content],{type})),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1400);}
function csv(rows){return '\ufeff'+rows.map(row=>row.map(v=>'"'+String(v??'').replace(/"/g,'""')+'"').join(';')).join('\r\n');}
function exportCsv(which){let data=[];
 if(which==='edt'){data=[['Código','Cuenta','Paquete','BAC COP','Peso','Inicio P','Fin P','Inicio S','Fin S','Gate','Riesgo','Criterio aceptación','Responsable','Dependencia','Regla EV','PV P0','PV P1','PV P2','PV P3','PV P4','PV P5','PV P6'],...D.packages.map(p=>[p.id,p.account,p.name,p.bac,p.weight,p.phaseStart,p.phaseEnd,p.weekStart,p.weekEnd,p.gate,p.risk,p.accept,p.owner,p.depends,p.evRule,...p.pvByPhase])]}
 if(which==='risks'){data=[['Código','Familia','Evento','P','I','P×I','Prioridad','Hipótesis','Gates','Disparador','Respuesta','EDT'],...D.risks.map(r=>[r.id,r.group,r.name,r.p,r.impact,r.p*r.impact,r.level,r.hypothesis,r.gates,r.trigger,r.action||r.response,r.packages.join('/')])];}
 if(which==='decisions'){data=[['EVM','Escenario financiero','PV','EV','AC','SPI','CPI','EAC trabajo','Reserva pendiente','EAC compromiso','Exceso techo','VPN','TIR E.A.','BC','Payback meses'],...D.evmCases.flatMap(e=>D.financialCases.map(f=>{const z=financialResult(f.id,e.id),v=z.evm;return [e.id,f.name,v.pv,v.ev,v.ac,v.spi,v.cpi,v.eacWork,v.reserve,v.commitment,v.excess,z.npv,z.irr,z.bc,z.payback]}))];}
 if(data.length){download(`NEXO_INNOVA_PI2_S6_${which}.csv`,csv(data),'text/csv;charset=utf-8');toast('CSV generado: '+which);}
}
function save(){const snapshot={schema:'NEXO_INNOVA_PI2_S6_v3_legacy',source:D.source,date:new Date().toISOString(),warning:'Sólo simulación académica; no registro empresarial.',controls:{...S},metrics:{evm:getEVM(),financial:financialResult(),comparisons:Object.fromEntries(D.evmCases.map(e=>[e.id,Object.fromEntries(D.financialCases.map(f=>[f.id,financialResult(f.id,e.id).npv]))]))}};
 // Avoid serializing unnecessary full monthly arrays in snapshots beyond the active scenario.
 download('NEXO_INNOVA_S6_simulacion.json',JSON.stringify(snapshot,null,2),'application/json;charset=utf-8');toast('Simulación guardada en JSON');}
function reset(){const tab=S.tab;S=initial();S.tab=tab;renderCurrent();toast('Controles restaurados a las fuentes originales');}
function updateRangeUI(k){const val=$('#r-'+k);if(val){val.textContent=k==='iterationDelta'?(S[k]>=0?'+':'')+dec(S[k],2)+' / desarrollo':k==='futureCpi'?dec(S[k],2):S[k]+(k==='extraHours'?' h':k==='delay'?' meses':' %');}}
function handleClick(e){const t=e.target.closest('button');if(!t)return;
 if(t.dataset['archiveGo']){if(t.dataset.selectVersion)S.actorVersion=t.dataset.selectVersion;S.archiveTab=t.dataset.archiveGo;nav('trazabilidad');return;}
 if(t.dataset.archiveTab){S.archiveTab=t.dataset.archiveTab;renderCurrent();return;}
 if(t.dataset.archiveH){S.archiveH=t.dataset.archiveH;S.archiveTab='evolucion';if(S.tab!=='trazabilidad')nav('trazabilidad');else renderCurrent();return;}
 if(t.dataset.archiveActor){S.archiveActor=t.dataset.archiveActor;S.archiveTab='evolucion';if(S.tab!=='trazabilidad')nav('trazabilidad');else renderCurrent();return;}
 if(t.dataset.archiveDelta){S.archiveDelta=t.dataset.archiveDelta;renderCurrent();return;}
 if(t.dataset.tab){nav(t.dataset.tab);return;}
 if(t.dataset.go){nav(t.dataset.go);return;}
 if(t.dataset.execution){S.execution=t.dataset.execution;renderCurrent();return;}
 if(t.dataset.finance){S.finance=t.dataset.finance;renderCurrent();return;}
 if(t.dataset.futuremode){S.futureMode=t.dataset.futuremode;S.futureCpi=1;renderCurrent();return;}
 if(t.dataset.matrix){const [ev,fin]=t.dataset.matrix.split('|');S.execution=ev;S.finance=fin;renderCurrent();toast(`Cruce: EVM ${ev} y financiero ${fin}`);return;}
 if(t.dataset.account){S.account=S.account===t.dataset.account?'all':t.dataset.account;nav('edt');return;}
 if(t.dataset.package){S.selectedPackage=t.dataset.package;S.account='all';S.gateFilter='all';S.packageSearch='';nav('edt');const el=$('#packageDetailHost');el?.scrollIntoView({behavior:'smooth',block:'center'});return;}
 if(t.dataset.risk){S.selectedRisk=t.dataset.risk;nav('riesgos');$('#riskDetailHost')?.scrollIntoView({behavior:'smooth',block:'center'});return;}
 if(t.dataset.riskTest){S.execution=t.dataset.riskTest;S.evidencePct=0;S.extraHours=0;S.futureMode='observed';nav('decisiones');toast(`EVM ${S.execution}: ensayo hipotético, no ocurrencia del riesgo`);return;}
 if(t.dataset.actorversion){S.actorVersion=t.dataset.actorversion;renderCurrent();return;}
 if(t.hasAttribute('data-clear-edt')){S.account='all';S.gateFilter='all';S.packageSearch='';renderCurrent();return;}
 if(t.hasAttribute('data-reset')){reset();return;}
 if(t.dataset.export){exportCsv(t.dataset.export);return;}
}
function handleInput(e){const t=e.target;if(t.dataset.range){const key=t.dataset.range;let v=Number(t.value);if(key==='iterationDelta')v=Math.round(v*100)/100;S[key]=v;updateRangeUI(key);updateSimOutputs();return;}
 if(t.id==='packageSearch'){S.packageSearch=t.value;const host=$('#packageTableHost');if(host)host.innerHTML=packageTable();const ganttHost=$('#ganttHost');if(ganttHost)ganttHost.innerHTML=gantt();return;}
 if(t.id==='riskSearch'){S.riskSearch=t.value;const host=$('#riskTableHost');if(host)host.innerHTML=riskTable();return;}}
function handleChange(e){const t=e.target;
 if(t.dataset.range){renderCurrent();return;}
 if(t.dataset.checkbox){S[t.dataset.checkbox]=Boolean(t.checked);renderCurrent();return;}
 if(t.dataset.gatecheck){S.gates[t.dataset.gatecheck]=Boolean(t.checked);renderCurrent();return;}
 if(t.id==='accountFilter'){S.account=t.value;renderCurrent();return;}
 if(t.id==='gateFilter'){S.gateFilter=t.value;renderCurrent();return;}
 if(t.id==='riskGroup'){S.riskGroup=t.value;renderCurrent();return;}
 if(t.id==='expenseMonth'){S.expenseMonth=clamp(Number(t.value),0,36);renderCurrent();return;}
}
window.NEXO_PI2={version:'S6-integrado-v2',data:D,state:()=>JSON.parse(JSON.stringify(S)),getEVM,financialResult,scenarioMatrix,reset};
document.addEventListener('click',e=>{if(e.target.id==='menuToggle'){$('#sidebar').classList.toggle('open');return;}if(e.target.id==='exportSnapshot'){save();return;}handleClick(e)});
document.addEventListener('input',handleInput);
document.addEventListener('change',handleChange);
renderCurrent();
})();
